-- Generated from src/notebooks/configs/linguaggiProgrammazioneConfig.js.
insert into public.guided_notebooks (slug, description, node_id, pending_node_slug, config)
select 'linguaggi-programmazione', 'Segui il percorso dal codice sorgente alle strategie di compilazione, ai runtime e alle istruzioni eseguite dalla CPU.', n.id,
  case when n.id is null then 'backend-languages' else null end,
  convert_from(decode('', 'base64'), 'UTF8')::jsonb
from (select 1) seed left join public.nodes n on n.slug = 'backend-languages'
on conflict (slug) do nothing;
